"""Validate neglect-map CSV files: required columns, citations, confidence values."""
import csv
import sys

REQUIRED = ["area", "org", "project", "approx_fte", "funding_source", "public_outputs",
            "last_activity", "source_urls", "confidence", "notes"]
CONF = {"low", "med", "high"}


def validate(path):
    errors = []
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        missing = [c for c in REQUIRED if c not in (reader.fieldnames or [])]
        if missing:
            return [f"missing columns: {missing}"]
        for i, row in enumerate(reader, start=2):
            if not row["source_urls"].strip():
                errors.append(f"line {i}: no source_urls (every row must be cited)")
            if row["confidence"].strip() not in CONF:
                errors.append(f"line {i}: confidence must be one of {sorted(CONF)}")
            if not row["area"].strip():
                errors.append(f"line {i}: empty area")
    return errors


if __name__ == "__main__":
    paths = sys.argv[1:] or ["neglect-map/schema.csv"]
    bad = False
    for p in paths:
        for e in validate(p):
            print(f"{p}: {e}")
            bad = True
    sys.exit(1 if bad else 0)
